import re

def eval_expression(expr):
    # トークナイズ: 数字(小数点含む)、演算子、括弧に分割する
    # 正規表現で数字、演算子 (+, -, *, /), 括弧 ( (, ) ) を抽出
    tokens = re.findall(r'\d+\.?\d*|[+\-*/()]', expr)
    pos = 0

    def peek():
        """現在のトークンを返す（位置は進めない）"""
        nonlocal pos
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        """現在のトークンを返して、位置を1つ進める"""
        nonlocal pos
        token = peek()
        pos += 1
        return token

    def parse_expression():
        """加減算を処理する (優先順位: 低)"""
        node = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                node += right
            else:
                node -= right
        return node

    def parse_term():
        """乗除算を処理する (優先順位: 中)"""
        node = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_factor()
            if op == '*':
                node *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                node /= right
        return node

    def parse_factor():
        """単項演算子、括弧、数値を処理する (優先順位: 高)"""
        token = peek()

        # 負の数や正の符号の処理 (unary operators)
        if token == '-':
            consume()
            return -parse_factor()
        if token == '+':
            consume()
            return parse_factor()

        # 括弧の処理
        if token == '(':
            consume() # '(' を消費
            result = parse_expression()
            if consume() != ')':
                raise ValueError("Missing closing parenthesis")
            return result

        # 数値の処理
        token = consume()
        if token is None:
            raise ValueError("Unexpected end of expression")
        try:
            return float(token)
        except ValueError:
            raise ValueError(f"Invalid token: {token}")

    # 最終的な計算結果を整数に変換できる場合は整数で返す
    result = parse_expression()
    if result.is_integer():
        return int(result)
    return result

# --- テストケース ---
if __name__ == "__main__":
    test_cases = [
        ("3 + 4 * (2 - 1)", 7),
        ("10 + 2 * 3", 16),
        ("(10 + 2) * 3", 36),
        ("-5 + 2", -3),
        ("2 * (-3 + 1)", -4),
        ("10 / 2 / 2", 2.5),
        ("10 / (2 + 3)", 2),
        ("-2 * -3", 6),
    ]

    for expr, expected in test_cases:
        res = eval_expression(expr)
        print(f"'{expr}' => {res} (Expected: {expected})")
        assert res == expected

    # ZeroDivisionError のテスト
    try:
        eval_expression("10 / 0")
    except ZeroDivisionError as e:
        print(f"Caught expected error: {e}")
